// src/components/SetAutocomplete.jsx
import React, { useState, useMemo } from 'react';
import setsFile from '../assets/setExampes.json';   // adjust the path to yours

/**
 * props:
 *   onSelect(set)  – (optional) callback fired when the user picks a set object
 */
export default function SetAutocomplete({ onSelect }) {
  const [query, setQuery] = useState('');

  // Simple fuzzy / substring match against name, id and series
  const filtered = useMemo(() => {
    const q = query.trim().toLowerCase();
    if (!q) return setsFile.data;                      // show all if no text
    return setsFile.data.filter(
      (s) =>
        s.name.toLowerCase().includes(q) ||
        s.id.toLowerCase().includes(q) ||
        s.series.toLowerCase().includes(q)
    );
  }, [query]);

  /** When a row is picked */
  const choose = (set) => {
    setQuery(set.name);        // fill the input with the chosen label
    onSelect?.(set);           // forward the whole object upstream
  };

  return (
    <div className="relative w-80">
      <input
        className="w-full rounded border px-3 py-2"
        placeholder="Search Pokémon set…"
        value={query}
        onChange={(e) => setQuery(e.target.value)}
      />

      {filtered.length > 0 && (
        <ul className="absolute z-10 mt-1 max-h-60 w-full overflow-y-auto rounded border bg-white shadow">
          {filtered.map((s) => (
            <li
              key={s.id}
              onMouseDown={() => choose(s)}          
              className="cursor-pointer px-3 py-1 hover:bg-indigo-100"
            >
              <span className="font-medium">{s.name}</span>
              <span className="ml-2 text-xs text-gray-500">({s.series})</span>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}
